    id: "portal-et-teemad-ilm-kliima-ilmajutud-j-c3-b5gevamaa-kliimast-f003bb",
    title: "Jõgevamaa kliimast",
    organization: "Keskkonnaagentuur",
    type: "Teemalehed > Sisuleht",
